	int z[N];
void solve(int CASE)
{
	string s; cin >> s;

	// s + '#'
	s.pb('#');
	int l = 0, r = 0;
	z[0] = 0;
	fa(i, 1, vs(s)) {
		if (i <= r)z[i] = min(z[i - l], r - i + 1);
		while (i + z[i] <= vs(s) and s[z[i]] == s[i + z[i]])z[i]++;
		if (i + z[i] - 1 > r)l = i, r = i + z[i] - 1;
	}

	int ans = 0;
	int n; cin >> n;
	while (n--) {
		// s + '#' + t
		string t; cin >> t;
		int res = 0;
		int l = vs(s), r = vs(s);
		fa(i, vs(s) + 1, vs(s) + 1 + vs(t)) {
			int nowz = 0;
			if (i <= r)nowz = max(nowz, min(z[i - l], r - i + 1));
			while (nowz <= vs(s) and i + nowz - vs(s) - 1 <= vs(t) and 
				s[nowz] == t[i + nowz - vs(s) - 1])nowz++;
			if (i + nowz - 1 > r)l = i, r = i + nowz - 1;
			res = max(res, nowz);
		}
		ans += res;
	}

	cout << ans << endl;
	return;
}
